  label: "campaign_dimension"
  type: string
  sql: ${user_records.campaign_source} ;;
}

dimension: campaign_name {
  label: "campaign_dimension"
  type: string
  sql: ${user_records.campaign_name} ;;
}

dimension: plan_name {
  label: "subscription_dimensions"
  type: string
  sql: case when ${subscription_records.subscription_length}=1 then '1 month' 
            when ${subscription_records.subscription_length}=3 then '3 month' 
            when ${subscription_records.subscription_length}=12 then '12 month' else 'other' end ;;
}

dimension: customer_age_band {
  label: "demographic_dimensions"
  type: string
  sql: case when datediff('year', ${user_records.dob}, current_date()) < 25 then '18-24' 
            when datediff('year', ${user_records.dob}, current_date()) < 35 then '25-34' 
            when datediff('year', ${user_records.dob}, current_date()) < 45 then '35-44' 
            when datediff('year', ${user_records.dob}, current_date()) < 55 then '45-54' 
            when datediff('year', ${user_records.dob}, current_date()) < 65 then '55-64' else '65+' end ;;
}

dimension: tenure_bucket {
  label: "demographic_dimensions"
  type: string
  sql: case when datediff('day', ${user_records.signup_ts}, current_date()) < 30 then '0-29 days' 
            when datediff('day', ${user_records.signup_ts}, current_date()) < 90 then '30-89 days' 
            when datediff('day', ${user_records.signup_ts}, current_date()) < 180 then '90-179 days'  
            when datediff('day', ${user_records.signup_ts}, current_date()) < 365 then '180-364 days' 
            else '365+ days' end ;;
}

dimension: cohort {
  label: "renewal_dimensions"
  type: string
  sql: datediff('month', ${subscription_records.subscription_start_ts}, ${scheduled_subscription_payment_records.scheduled_payment_ts}) ;;
}

