  label: "subscription lifecycle"
  type: string
  sql: case when datediff('day', ${subscription_records.subscription_start_ts}, current_date()) < 30 then '0-29 days' 
            when datediff('day', ${subscription_records.subscription_start_ts}, current_date()) < 90 then '30-89 days' 
            when datediff('day', ${subscription_records.subscription_start_ts}, current_date()) < 180 then '90-179 days'  
            when datediff('day', ${subscription_records.subscription_start_ts}, current_date()) < 365 then '180-364 days' 
            else '365+ days' end ;;
